const MarkUserDataExportReady = `-- name: MarkUserDataExportReady :one
UPDATE user_data_exports
SET ready_at = $1,
    expires_at = $2,
    object_key = $3,
    size_bytes = $4
WHERE tenant_id = $5
    AND id = $6
    AND claimed_at = $7
    AND ready_at IS NULL
    AND failed_at IS NULL
    AND user_id IS NOT NULL
RETURNING id, tenant_id, user_id, requested_at, claimed_at, ready_at, failed_at, expires_at, object_key, size_bytes
`

type MarkUserDataExportReadyParams struct {
	ReadyAt   sql.NullTime   `json:"ready_at"`
	ExpiresAt sql.NullTime   `json:"expires_at"`
	ObjectKey sql.NullString `json:"object_key"`
	SizeBytes sql.NullInt64  `json:"size_bytes"`
	TenantID  uuid.UUID      `json:"tenant_id"`
	ID        uuid.UUID      `json:"id"`
	ClaimedAt sql.NullTime   `json:"claimed_at"`
}

// Records the stored archive, as long as the claim is still the one that
// built it and the account still exists. No row otherwise, and the archive is
// then nobody's.
func (q *Queries) MarkUserDataExportReady(ctx context.Context, arg MarkUserDataExportReadyParams) (UserDataExport, error) {
	row := q.db.QueryRowContext(ctx, MarkUserDataExportReady,
		arg.ReadyAt,
		arg.ExpiresAt,
		arg.ObjectKey,
		arg.SizeBytes,
		arg.TenantID,
		arg.ID,
		arg.ClaimedAt,
	)
	var i UserDataExport
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.UserID,
		&i.RequestedAt,
		&i.ClaimedAt,
		&i.ReadyAt,
		&i.FailedAt,
		&i.ExpiresAt,
		&i.ObjectKey,
		&i.SizeBytes,
	)
	return i, err
}
